   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

var nOff = 0;
var pointDensity = 10;
var colors;

function setup() {
  //let mySize = max(windowWidth, windowHeight);
  createCanvas(windowWidth, windowHeight);
  //frameRate(30);
  colorMode(HSB, 360, 100, 100, 100);

  pixelDensity(5);
  background(0, 0, 95, 100);
}

function draw() {
  colors = [
    color(200, random(90, 70), random(20), random(85, 100)),
    color(120, random(30, 50), 90, random(85, 100)),
    color(280, random(30, 50), 90, random(85, 100)),
    color(180, random(30, 50), 90, random(85, 100)),
    color(280, random(30, 50), 90, random(85, 100)),
    color(30, random(90, 50), 90, random(85, 100)),
    color(90, random(30, 50), 90, random(85, 100)),
    color(150, random(10, 50), 90, random(85, 100)),
    color(210, random(70, 50), 90, random(85, 100)),
  ];
  nOff = nOff + 1;
  for (let x = -width * 0.1; x < width * 1.1; x += pointDensity * 2) {
    for (let y = -height * 0.1; y < height * 1.1; y += pointDensity) {
      push();
      translate(x, y);
      strokeCap(SQUARE);
      strokeWeight(0.5);
      let num = noise((x + nOff) / 10, y / 10);

      if (num < 0.15) {
        noStroke();
        fill(random(colors));
      } else if (num >= 0.15 && num < 0.55) {
        stroke(random(colors));
        fill(random(colors));
      } else if (num >= 0.55 && num < 0.65) {
        noFill();
        stroke(random(colors));
      } 
      let quadX = pointDensity;
      let quadY = pointDensity;
      let plusY = 2 * pointDensity;
      //quad(0, 0, 0, quadY, quadX, quadY-plusY, quadX,  - plusY);
      quad(0, 0, 0, quadY, -quadX, quadY - plusY, -quadX, -plusY);

      pop();
    }
  }

  for (let x = -width * 0.1; x < width * 1.1; x += pointDensity * 2) {
    for (let y = -height * 0.1; y < height * 1.1; y += pointDensity) {
      noStroke();
      push();
      translate(x, y);
      var num = noise((x + nOff) / 10, y / 10);
      //print(num);
      if (num < 0.25) {
        fill(random(colors));
      } else if (num >= 0.25 && num < 0.5) {
        fill(random(colors));
      } else if (num >= 0.5 && num < 0.7) {
        fill(random(colors));
      }
      var quadX = pointDensity;
      var quadY = pointDensity;
      var plusY = 2 * pointDensity;
      quad(0, 0, 0, quadY, quadX, quadY - plusY, quadX, -plusY);
      //quad(0, 0, 0, quadY, -quadX, quadY-plusY, -quadX,  - plusY);

      pop();
    }
  }
  noLoop();
}

function mouseClicked(){
	loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("DotandDashLine-004", "png");
  }
}

